#include <stdio.h>

#define MAX 505

int N, M;
char grid[MAX][MAX];

int qx[MAX * MAX];
int qy[MAX * MAX];
int head = 0, tail = 0;

void push(int r, int c) {
    qx[tail] = r;
    qy[tail] = c;
    tail++;
}

int main() {
    if (scanf("%d %d", &N, &M) != 2) return 0;

    for (int i = 0; i < N; i++) {
        scanf("%s", grid[i]);
    }

    for (int i = 0; i < N; i++) {
        for (int j = 0; j < M; j++) {
            if (grid[i][j] == 'o') {
                push(i, j);
            }
        }
    }

    while (head < tail) {
        int r = qx[head];
        int c = qy[head];
        head++;

        // Regra 1: Água cai verticalmente
        if (r + 1 < N && grid[r + 1][c] == '.') {
            grid[r + 1][c] = 'o';
            push(r + 1, c);
        }

        // Regra 2 e 3: Se houver prateleira embaixo, água escorre para os lados
        if (r + 1 < N && grid[r + 1][c] == '#') {
            if (c - 1 >= 0 && grid[r][c - 1] == '.') {
                grid[r][c - 1] = 'o';
                push(r, c - 1);
            }
            if (c + 1 < M && grid[r][c + 1] == '.') {
                grid[r][c + 1] = 'o';
                push(r, c + 1);
            }
        }
    }

    for (int i = 0; i < N; i++) {
        printf("%s\n", grid[i]);
    }

    return 0;
}
